// === harga.js ===
export const PAJAK = 0.11;
export function denganPajak(n) {
  return Math.round(n * (1 + PAJAK));
}
const rahasia = 'tidak diekspor';
// === main.js ===
import { denganPajak, PAJAK } from './harga.js';
console.log(PAJAK);
console.log(denganPajak(18000));
console.log(typeof rahasia);

