// === menu.js ===
export const MENU = [
  { kode: 'K01', nama: 'Kopi Susu', harga: 18000 },
  { kode: 'T01', nama: 'Teh Tarik', harga: 12000 },
];
// === main.js ===
import { MENU } from './menu.js';
console.log('Jumlah menu:', MENU.length);

// === menu.js ===
export const MENU = [
  { kode: 'K01', nama: 'Kopi Susu', harga: 18000 },
  { kode: 'T01', nama: 'Teh Tarik', harga: 12000 },
];
export function cariMenu(kode) {
  return MENU.find((m) => m.kode === kode);
}
// === main.js ===
import { MENU, cariMenu } from './menu.js';
console.log('Jumlah menu:', MENU.length);
const k = cariMenu('K01');
console.log(k.nama, k.harga);

